genereti_widget_values.guide:
{
  "format": "genereti-guide",
  "version": 1,
  "id": "genereticore-08-arcade",
  "title": "Blocks & Beats · a decision arcade",
  "summary": "Learn on this editable graph. Inference starts only when you press Run.",
  "steps": [
    {
      "title": "Open the arcade",
      "text": "ꘅ Decision Arcade · open Blocks & Beats\n\nClick ▦. The demo opens locally and stays idle until Start game.",
      "target": {
        "nodeType": "GeneretiCoreDecisionArcade",
        "nodeId": 2,
        "ref": "8884c7f8-7510-59d5-b1b5-433db11bb533",
        "part": "node"
      },
      "hint": "Follow the note at the top of the workflow. Top Run updates connected nodes."
    },
    {
      "title": "Follow a move",
      "text": "ꘅ Decision Arcade · open Blocks & Beats\n\nIn the demo page, compare A–D candidates and the JSON decision. These options are legal placements, not raw keypresses.",
      "target": {
        "nodeType": "GeneretiCoreDecisionArcade",
        "nodeId": 2,
        "ref": "8884c7f8-7510-59d5-b1b5-433db11bb533",
        "part": "node"
      },
      "hint": "Follow the note at the top of the workflow. Top Run updates connected nodes."
    },
    {
      "title": "Conduct the soundtrack",
      "text": "ꘅ Decision Arcade · open Blocks & Beats\n\nStart audio explicitly. Compare current and next music patterns; changes land on bar boundaries.",
      "target": {
        "nodeType": "GeneretiCoreDecisionArcade",
        "nodeId": 2,
        "ref": "8884c7f8-7510-59d5-b1b5-433db11bb533",
        "part": "node"
      },
      "hint": "Follow the note at the top of the workflow. Top Run updates connected nodes."
    },
    {
      "title": "Compare decision strategies",
      "text": "ꘅ Decision Arcade · open Blocks & Beats\n\nReset to seed 7 and select the heuristic player for a no-model baseline. Compare holes, height and cleared rows; d1 is not promised to win.",
      "target": {
        "nodeType": "GeneretiCoreDecisionArcade",
        "nodeId": 2,
        "ref": "8884c7f8-7510-59d5-b1b5-433db11bb533",
        "part": "node"
      },
      "hint": "Follow the note at the top of the workflow. Top Run updates connected nodes."
    }
  ]
}

